<script setup>
import {computed,reactive,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import Icon from '../components/Icon.vue'
import RoomCard from '../components/RoomCard.vue'
import {rooms,money} from '../data'
import {state,validateField} from '../store'
const route=useRoute(),router=useRouter(),houses=computed(()=>route.params.kind==='nha-tro'),saved=computed(()=>route.params.kind==='da-luu'),modal=ref(''),deleting=ref(null),editingId=ref(null),notice=ref(''),errors=reactive({}),form=reactive({name:'',address:'',rooms:1,status:'Đang hoạt động',desc:''}),more=ref(false)
const list=computed(()=>saved.value?rooms.filter(r=>state.favorites.includes(r.id)):state.posts)
function open(h){editingId.value=h?.id||null;Object.assign(form,h||{name:'',address:'',rooms:1,status:'Đang hoạt động',desc:''});Object.keys(errors).forEach(k=>delete errors[k]);modal.value='house'}
function save(){Object.keys(errors).forEach(k=>delete errors[k]);for(const k of ['name','address'])if(!form[k].trim())errors[k]='Vui lòng điền thông tin này.';if(Number(form.rooms)<=0)errors.rooms='Số phòng phải lớn hơn 0.';if(Object.keys(errors).length)return;const item={...form,id:editingId.value||'house-'+Date.now()};if(editingId.value)Object.assign(state.houses.find(h=>h.id===editingId.value),item);else state.houses.push(item);modal.value='';notice.value='Đã lưu thông tin nhà trọ trên thiết bị này.'}
function remove(){if(houses.value){state.houses=state.houses.filter(h=>h.id!==deleting.value.id);state.posts=state.posts.filter(p=>p.houseId!==deleting.value.id)}else state.posts=state.posts.filter(p=>p.id!==deleting.value.id);deleting.value=null;notice.value='Đã xóa và cập nhật danh sách.'}
</script>
<template><div v-if="!state.user" class="container empty-state"><Icon name="building" :size="42"/><h1>Quản lý không gian của bạn</h1><p>Đăng nhập để quản lý nhà trọ và bài đăng.</p><RouterLink :to="'/dang-nhap?redirect='+encodeURIComponent(route.fullPath)" class="button primary">Đăng nhập</RouterLink></div><div v-else-if="houses&&state.user.role!=='landlord'" class="container empty-state"><Icon name="building" :size="42"/><h1>Không gian dành cho chủ trọ</h1><p>Bạn đang đăng nhập với vai trò sinh viên.</p><RouterLink to="/ho-so" class="button secondary">Về hồ sơ</RouterLink></div><div v-else class="container page"><div class="section-heading"><div><span class="eyebrow">Không gian của bạn</span><h1>{{houses?'Quản lý nhà trọ':saved?'Tin đã lưu':'Quản lý bài đăng trọ'}}</h1></div><button v-if="houses" class="button primary" @click="open()"><Icon name="plus" :size="18"/>Thêm nhà trọ</button><RouterLink v-else-if="!saved" :to="'/dang-bai/'+(state.user.role==='landlord'?'rental':'roommate')" class="button primary"><Icon name="plus" :size="18"/>{{state.user.role==='landlord'?'Đăng bài cho thuê':'Đăng bài ghép trọ'}}</RouterLink></div><p v-if="notice" class="notice" role="status">{{notice}}</p><template v-if="houses"><div class="table-header"><span>Thông tin nhà trọ</span><span>Địa chỉ</span><span>Số phòng</span><span>Thao tác</span></div><article v-for="h in state.houses" :key="h.id" class="house-row"><div><h3>{{h.name}}</h3><p class="muted">{{h.desc}}</p></div><p>{{h.address}}</p><span>{{h.rooms}} phòng</span><div class="inline"><button class="icon-button outlined" @click="open(h)" :aria-label="'Chỉnh sửa '+h.name"><Icon name="edit" :size="17"/></button><button class="icon-button outlined danger-text" @click="deleting=h" :aria-label="'Xóa '+h.name"><Icon name="trash" :size="17"/></button></div></article><div v-if="!state.houses.length" class="empty-state"><h2>Chưa có nhà trọ</h2><p>Thêm nhà trọ đầu tiên để bắt đầu đăng tin cho thuê.</p><button class="button primary" @click="open()">Thêm nhà trọ</button></div></template><div v-else-if="saved&&list.length" class="room-grid"><RoomCard v-for="r in list" :key="r.id" :room="r"/></div><template v-else-if="!saved&&list.length"><div class="manage-list"><article v-for="r in list.slice(0,more?list.length:3)" :key="r.id" class="manage-post"><img :src="r.image" :alt="r.title"><div class="manage-post-info"><span class="badge cream">{{r.status}}</span><h3>{{r.title}}</h3><p class="muted">{{r.address||'Cần Thơ'}} · {{r.area}} m²</p><p class="price">{{money(r.price)}}<span> / tháng</span></p></div><div class="manage-post-actions"><RouterLink :to="'/dang-bai/'+(r.kind||'rental')+'?edit='+r.id" class="button secondary small"><Icon name="edit" :size="16"/>Chỉnh sửa</RouterLink><button class="icon-button outlined danger-text" @click="deleting=r" :aria-label="'Xóa bài '+r.title"><Icon name="trash" :size="18"/></button></div></article></div><div class="center section-action" v-if="list.length>3"><button class="button secondary" @click="more=!more">{{more?'Thu gọn':'Xem thêm'}}<Icon name="down" :size="18"/></button></div></template><div v-else class="empty-state"><span class="empty-icon"><Icon :name="saved?'heart':'grid'" :size="38"/></span><h2>{{saved?'Bạn chưa lưu phòng nào':'Chưa có bài đăng'}}</h2><p>{{saved?'Lưu lại những căn phòng bạn muốn xem thêm.':'Bắt đầu bằng một bài đăng giới thiệu không gian của bạn.'}}</p><RouterLink :to="saved?'/tim-tro':'/dang-bai/'+(state.user.role==='landlord'?'rental':'roommate')" class="button primary">{{saved?'Tìm phòng trọ':'Tạo bài đăng'}}</RouterLink></div><Teleport to="body"><div v-if="deleting" class="modal-backdrop" @click.self="deleting=null" @keydown.esc="deleting=null"><section class="modal" v-dialog-focus role="dialog" aria-modal="true" aria-labelledby="delete-title"><span class="empty-icon coral"><Icon name="trash" :size="28"/></span><h2 id="delete-title">{{houses?'Xóa nhà trọ này?':'Xóa bài đăng này?'}}</h2><p>{{deleting.name||deleting.title}}</p><p class="muted">{{houses?'Bài đăng gắn với nhà trọ cũng sẽ được ẩn.':'Bài đăng sẽ được gỡ khỏi danh sách trên thiết bị này.'}}</p><div class="form-actions"><button class="button secondary" @click="deleting=null">Hủy</button><button class="button danger" @click="remove">Xác nhận xóa</button></div></section></div><div v-if="modal==='house'" class="modal-backdrop" @click.self="modal=''" @keydown.esc="modal=''"><section class="modal large" v-dialog-focus role="dialog" aria-modal="true" aria-labelledby="house-title"><div class="section-heading"><h2 id="house-title">{{editingId?'Chỉnh sửa nhà trọ':'Tạo nhà trọ'}}</h2><button class="icon-button" @click="modal=''" aria-label="Đóng"><Icon name="close"/></button></div><form @submit.prevent="save"><label class="field"><span>Tên nhà trọ *</span><input v-model="form.name" placeholder="Ví dụ: Nhà trọ Minh An" :aria-invalid="!!errors.name"><small class="error">{{errors.name}}</small></label><label class="field"><span>Địa chỉ *</span><input v-model="form.address" placeholder="Số nhà, đường, phường, Cần Thơ" :aria-invalid="!!errors.address"><small class="error">{{errors.address}}</small></label><label class="field"><span>Số phòng *</span><input type="number" min="1" v-model.number="form.rooms"><small class="error">{{errors.rooms}}</small></label><label class="field"><span>Mô tả nhà trọ</span><textarea v-model="form.desc" rows="3" placeholder="Không gian, an ninh, tiện nghi…"></textarea></label><div class="form-actions"><button type="button" class="button secondary" @click="modal=''">Hủy</button><button class="button primary">Lưu nhà trọ</button></div></form></section></div></Teleport></div></template>
